/* Real host + real Space panel. Owns windows; never injects physical input. */
#define COBJMACROS
#define wWinMain space_unused_host_entrypoint
#include "../app/fpdemo.c"
#undef wWinMain
static int passed,failed;static wchar_t left[32768],right[32768];
#define CHECK(label,condition) do{if(condition){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static void pump_space(int ms){uint64_t end=GetTickCount64()+ms;do{MSG m;while(PeekMessageW(&m,NULL,0,0,PM_REMOVE))if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(2);}while(GetTickCount64()<end);}
static const wchar_t *space_test_name(Pane *p){return p->view&&p->cursor<p_count(p)?fpe_view_name(p->view,p->cursor):NULL;}
static int wait_space(void){uint64_t end=GetTickCount64()+15000;while(g_space_state==SP_RUNNING&&GetTickCount64()<end)pump_space(5);return g_space_state==SP_COMPLETE;}
static void test_space_host_explicit_root_and_reuse(void){CHECK("ordinary browsing leaves analyzer dormant",!sidepanel_running(space_app()));fn_ctx c;app_pane_ctx(&c,&g.panes[0],FN_FROM_CODE);c.n=0;c.dirs=0;c.state=FN_S_FOLDER;c.dir=left;CHECK("Analyze space is a registered applicable command",fn_find("file.analyze_space")&&fn_applies(fn_find("file.analyze_space"),&c));fn_run(fn_find("file.analyze_space"),&c);app_ctx_free(&c);CHECK("real helper completes the captured Windows root",wait_space()&&g_space_root&&!wcscmp(g_space_root,left));uint64_t session=g_space_request.session;uint32_t generation=sidepanel_generation(space_app());p_navigate(&g.panes[0],right,NULL,1);pump_space(100);CHECK("pane navigation does not retarget analysis",!wcscmp(g_space_root,left)&&g_space_request.session==session);sidepanel_close();pump_space(50);CHECK("hiding preserves the owned analyzer process",sidepanel_running(space_app()));pane_run(active_pane(),"space.show",FN_FROM_CODE);pump_space(50);CHECK("reopening reuses results and process",sidepanel_open()&&sidepanel_generation(space_app())==generation&&g_space_request.session==session);}
static void request_action(uint64_t session,uint32_t action,const wchar_t *path){space_action a={session,action,0};size_t n=(wcslen(path)+1)*2;uint8_t *payload=malloc(sizeof a+n);memcpy(payload,&a,sizeof a);memcpy(payload+sizeof a,path,n);panel_message(space_app(),PANELP_SPACE_ACTION,payload,(uint32_t)(sizeof a+n));free(payload);}
static void test_space_host_scope_and_real_pane_actions(void){wchar_t target[32768];swprintf(target,32768,L"%ls\\notes.md",left);uint64_t session=g_space_request.session;uint64_t before=g.panes[1].nav_ticket;request_action(session+1,SPACE_RIGHT,target);CHECK("stale result session is refused",g.panes[1].nav_ticket==before);wchar_t outside[32768];swprintf(outside,32768,L"%ls\\notes.md",right);request_action(session,SPACE_RIGHT,outside);CHECK("outside-root result action is refused",g.panes[1].nav_ticket==before);request_action(session,SPACE_RIGHT,target);uint64_t until=GetTickCount64()+7000;while((!g.panes[1].path||wcscmp(g.panes[1].path,left)||space_test_name(&g.panes[1])==NULL||wcscmp(space_test_name(&g.panes[1]),L"notes.md"))&&GetTickCount64()<until)pump_space(5);CHECK("Reveal right selects the real result in the right pane",g.panes[1].path&&!wcscmp(g.panes[1].path,left)&&space_test_name(&g.panes[1])&&!wcscmp(space_test_name(&g.panes[1]),L"notes.md"));pane_run(active_pane(),"space.show",FN_FROM_CODE);pump_space(50);request_action(session,SPACE_PREVIEW,target);until=GetTickCount64()+7000;while(g.pv_shown!=3&&GetTickCount64()<until)pump_space(5);CHECK("Preview routes through the existing real text reader",g.pv_shown==3&&IsWindowVisible(textview_window()));space_open_root(right);CHECK("explicit new root starts a new scan session",g_space_request.session!=session&&wait_space()&&!wcscmp(g_space_root,right));}
static void test_space_main_layout_and_catalog_authority(void){preview_hide();layout();space_open_root(left);CHECK("main analyzer completes owned root",wait_space());RECT host,panel;GetClientRect(g.hwnd,&host);GetWindowRect(sidepanel_window(),&panel);CHECK("Space replaces browsing tree and panes",!IsWindowVisible(T.hwnd)&&!IsWindowVisible(g.panes[0].hwnd)&&!IsWindowVisible(g.panes[1].hwnd)&&panel.right-panel.left>host.right*8/10);uint64_t session=g_space_request.session;request_action(session,SPACE_RIGHT,L"C:\\Windows\\forged");CHECK("outside scan result remains unauthorized in full view",g_space_request.session==session);space_action a={session+1,0,0};uint8_t data[sizeof a+8];memcpy(data,&a,sizeof a);memcpy(data+sizeof a,L"C:\\",8);panel_message(space_app(),PANELP_SPACE_VOLUME,data,sizeof data);CHECK("stale drive click cannot change scan authority",g_space_request.session==session);a.session=session;memcpy(data,&a,sizeof a);panel_message(space_app(),PANELP_SPACE_VOLUME,data,sizeof data);CHECK("registered drive click receives fresh host scan authority",g_space_request.session!=session&&!wcscmp(g_space_root,L"C:\\"));space_open_root(left);CHECK("replacement root drains pending drive scan",wait_space());sidepanel_show(g.hwnd,git_app(),SIDEPANEL_KEEP,0);pump_space(50);CHECK("switching tools restores file panes",IsWindowVisible(g.panes[0].hwnd));sidepanel_show(g.hwnd,space_app(),SIDEPANEL_KEEP,0);pump_space(50);CHECK("returning to Space restores main geometry",!IsWindowVisible(g.panes[0].hwnd));sidepanel_close();pump_space(30);CHECK("Files restores retained browsing panes",IsWindowVisible(g.panes[0].hwnd)&&IsWindowVisible(g.panes[1].hwnd));sidepanel_stop_app(git_app());}
static void test_space_host_disabled_feature_stops_owned_helper(void){const char *settings="[functions]\nfile.analyze_space = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();pump_space(50);CHECK("disabled analyzer cannot launch or accept actions",!fn_active(fn_find("file.analyze_space"))&&!sidepanel_running(space_app()));char report[65536];fn_report_csv(report,sizeof report);CHECK("host registry retains its lifetime contract",strstr(report,"metric,fn_violations,,,,0,")!=NULL);}
int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;wcsncpy(left,argv[1],32767);wcsncpy(right,argv[2],32767);CoInitializeEx(NULL,COINIT_APARTMENTTHREADED);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);fn_host host={host_now,host_arm,host_status};fn_init(&host);fn_register(app_functions,sizeof app_functions/sizeof *app_functions);functions_register();relay_register();palette_register();const char *settings="[functions]\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();g.engine=fpe_engine_create(NULL);g.dual=1;g.ratio=0.5;session_defaults(&g_ses);for(int i=0;i<2;i++){Pane *p=&g.panes[i];p->idx=i;p->ntabs=1;p->drop_row=-1;p->opts.dirs_first=1;}HINSTANCE instance=GetModuleHandleW(NULL);register_class(L"OpenPilot",main_proc,0,instance);register_class(L"OpenPilotPane",pane_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotTree",tree_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotDebug",dbg_proc,0,instance);HWND window=CreateWindowExW(0,L"OpenPilot",L"Owned Space integration",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,80,80,1300,820,NULL,NULL,instance,NULL);if(!window)return 3;for(int i=0;i<2;i++){fpe_dir *dir=read_start(i?right:left);if(dir){p_show_dir(&g.panes[i],dir,NULL,0);fpe_dir_release(dir);}}ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump_space(20);test_space_host_explicit_root_and_reuse();test_space_host_scope_and_real_pane_actions();test_space_main_layout_and_catalog_authority();test_space_host_disabled_feature_stops_owned_helper();DestroyWindow(window);pump_space(100);settings_save_join();folderwatch_join();fpe_engine_destroy(g.engine);free(g_space_root);CoUninitialize();printf("%d passed, %d failed; 4 Space host selectors\n",passed,failed);return failed?1:0;}
